def encode_image(path_or_url):
    """Encode image to base64 from file path or URL."""
    if path_or_url.startswith(("http://", "https://")):
        verbose(f"Downloading image from {path_or_url}")
        try:
            with urlopen(path_or_url, timeout=30) as resp:
                return base64.b64encode(resp.read()).decode("utf-8")
        except Exception as e:
            error(f"Failed to download image: {e}")
            sys.exit(EXIT_ERROR)
    else:
        path = Path(path_or_url)
        if not path.exists():
            error(f"File not found: {path_or_url}")
            sys.exit(EXIT_USAGE)
        verbose(f"Reading image from {path}")
        return base64.b64encode(path.read_bytes()).decode("utf-8")

